param([string]$Configuration='Release')
$ErrorActionPreference='Stop';$workspace=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$path=Join-Path $workspace "backend/SanSo.Migrator.V3/bin/$Configuration/net9.0/Migrations";if(!(Test-Path -LiteralPath $path)){throw 'MIGRATOR_V3_OUTPUT_NOT_FOUND'};$files=@(Get-ChildItem -LiteralPath $path -Filter *.sql -File|Sort-Object Name);$actual=@($files|ForEach-Object{if($_.Name-notmatch'^([0-9]{3})_'){throw "MIGRATION_NAME_INVALID: $($_.Name)"};$Matches[1]});$expected=1..10|ForEach-Object{$_.ToString('000')};if(($actual-join',')-ne($expected-join',')){throw "MIGRATION_SEQUENCE_INVALID: $($actual-join ',')"};$projection=Get-Content -LiteralPath(Join-Path $path '010_file_import_projection.sql')-Raw;foreach($guard in @('project_file_import_order_v1','ORDER_IMPORTED','ON CONFLICT(organization_id,source_key) DO NOTHING','calculated_amount,source_ref','NEEDS_REVIEW','RULE_OR_CATEGORY_REQUIRED')){if($projection-notmatch[regex]::Escape($guard)){throw "PROJECTION_GUARD_MISSING: $guard"}};if($projection-match"calculated_amount[^\n]+[0-9]"){throw 'TAX_AMOUNT_MUST_NOT_BE_INVENTED'};Write-Output "MIGRATION_MANIFEST_V5_VERIFIED count=$($files.Count) range=$($actual[0])-$($actual[-1]) projection=fail-closed-no-tax-guess"
